/** Todas as seções, já com Conta, Notificações e Acompanhamento refeitas. */
function sections(page) {
  const items = page.settingsItems();
  const user = page.user;
  if (items.has('account')) {
    items.setContent('account', m(FieldSet, {
      className: "Settings-account FieldSet--col",
      label: app.translator.trans('core.forum.settings.account_heading')
    }, m(AccountSection, {
      user: user,
      items: page.accountItems()
    })));
  }
  if (items.has('notifications')) {
    const notifications = page.notificationsItems();
    const tracking = new ItemList();
    TRACKING_ITEMS.forEach(key => {
      if (!notifications.has(key)) return;
      tracking.add(key, notifications.get(key), notifications.getPriority(key));
      notifications.remove(key);
    });
    items.setContent('notifications', m(FieldSet, {
      className: "Settings-notifications FieldSet--min",
      label: app.translator.trans('core.forum.settings.notifications_heading')
    }, notifications.toArray()));
    if (!tracking.isEmpty()) {
      items.add('canelaAutoTrack', m(FieldSet, {
        className: "Settings-canelaAutoTrack FieldSet--col",
        label: t('user.preferences.auto_track_heading')
      }, tracking.toArray()), 50);
    }
  }
  if (isTagsEnabled()) items.add('canelaNavMenu', navMenuSection(), 10);
  return items;
}
